 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    # The solid marker line is the floor/ceiling toward which the pieces fall.
    separator = None
    direction = None
    for r, row in enumerate(grid):
        if row and len(set(row)) == 1 and row[0] != 0:
            separator, direction = r, 1 if r == 0 else -1
            break
    if separator is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if vals and len(set(vals)) == 1 and vals[0] != 0:
                separator, direction = c, 1 if c == 0 else -1
                break
    if separator is None:
        return [row[:] for row in grid]

    # Extract each 4-connected nonzero object, excluding the separator line.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (direction == 1 and r == separator) or (direction == -1 and r == separator) or (r, c) in seen:
                continue
            cells = set()
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                rr, cc = q.popleft()
                cells.add((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc)); q.append((nr,nc))
            objects.append((color, cells))

    occupied = {cell for _, cells in objects for cell in cells}
    # Repeatedly let pieces closest to the separator move first.
    while True:
        moved = False
        if direction == 1:
            ordered = sorted(objects, key=lambda obj: min(r for r, _ in obj[1]))
        else:
            ordered = sorted(objects, key=lambda obj: -max(r for r, _ in obj[1]))
        for color, cells in ordered:
            shifted = {(r + direction, c) for r, c in cells}
            if any(r < 0 or r >= h or c < 0 or c >= w for r, c in shifted):
                continue
            if shifted & (occupied - cells):
                continue
            occupied.difference_update(cells)
            occupied.update(shifted)
            objects[objects.index((color, cells))] = (color, shifted)
            moved = True
        if not moved:
            break

    out = [[0] * w for _ in range(h)]
    for color, cells in objects:
        for r, c in cells:
            out[r][c] = color
    # Keep the solid separator exactly as given.
    out[separator] = grid[separator][:]
    return out
